1	import React, { useEffect, useState } from 'react';
2	
3	// The detail of a single invoice, shown when an invoice is opened from the project's invoice list.
4	// Owns its own state (CLAUDE.md — features own their state). Lists the invoice's line items — the
5	// things being charged for (description, quantity, unit price) — a derived total (the sum of each
6	// line's qty * unit price), and a form to add another line. Amounts render with 2 decimals.
7	type LineItem = {
8	  id: number;
9	  invoiceId: number;
10	  description: string;
11	  qty: number;
12	  unit: string;
13	  unitPrice: number;
14	};
15	
16	function money(n: number): string {
17	  return Number(n).toLocaleString('en-US', { style: 'currency', currency: 'USD' });
18	}
19	
20	type EditDraft = { description: string; qty: string; unit: string; unitPrice: string };
21	
22	// A payment a client has made against this invoice: how much (amount) and when (date, yyyy-MM-dd).
23	type Payment = {
24	  id: number;
25	  invoiceId: number;
26	  amount: number;
27	  date: string;
28	};
29	
30	export function InvoiceDetail({ invoiceId }: { invoiceId: number }) {
31	  const [lineItems, setLineItems] = useState<LineItem[]>([]);
32	  const [description, setDescription] = useState('');
33	  const [qty, setQty] = useState('');
34	  const [unit, setUnit] = useState('');
35	  const [unitPrice, setUnitPrice] = useState('');
36	  const [editingId, setEditingId] = useState<number | null>(null);
37	  const [draft, setDraft] = useState<EditDraft>({
38	    description: '',
39	    qty: '',
40	    unit: '',
41	    unitPrice: '',
42	  });
43	  const [payments, setPayments] = useState<Payment[]>([]);
44	  const [paymentAmount, setPaymentAmount] = useState('');
45	  const [paymentDate, setPaymentDate] = useState('');
46	  const [status, setStatus] = useState('');
47	  const [discountPct, setDiscountPct] = useState(0);
48	  const [taxPct, setTaxPct] = useState(0);
49	
50	  async function load() {
51	    const res = await fetch(`/api/lineitems?invoiceId=${invoiceId}`);
52	    if (res.ok) {
53	      setLineItems(await res.json());
54	    }
55	  }
56	
57	  async function loadPayments() {
58	    const res = await fetch(`/api/payments?invoiceId=${invoiceId}`);
59	    if (res.ok) {
60	      setPayments(await res.json());
61	    }
62	  }
63	
64	  // The invoice's status is worked out server-side from the payments recorded against it, so we
65	  // re-read it whenever the payments change rather than tracking it by hand. The invoice also
66	  // carries its discount and tax percentages, which we read here to show the discount, the tax and
67	  // the final total.
68	  async function loadStatus() {
69	    const res = await fetch(`/api/invoices/get?id=${invoiceId}`);
70	    if (res.ok) {
71	      const inv: { status: string; discountPct: number; taxPct: number } = await res.json();
72	      setStatus(inv.status);
73	      setDiscountPct(Number(inv.discountPct));
74	      setTaxPct(Number(inv.taxPct));
75	    }
76	  }
77	
78	  useEffect(() => {
79	    void load();
80	    void loadPayments();
81	    void loadStatus();
82	  }, [invoiceId]);
83	
84	  async function onRecordPayment(e: React.FormEvent) {
85	    e.preventDefault();
86	    const res = await fetch('/api/payments', {
87	      method: 'POST',
88	      headers: { 'Content-Type': 'application/json' },
89	      body: JSON.stringify({
90	        invoiceId,
91	        amount: Number(paymentAmount),
92	        date: paymentDate,
93	      }),
94	    });
95	    if (res.ok) {
96	      const created: Payment = await res.json();
97	      setPayments((prev) => [...prev, created]);
98	      setPaymentAmount('');
99	      setPaymentDate('');
100	      void loadStatus();
101	    }
102	  }
103	
104	  async function onSubmit(e: React.FormEvent) {
105	    e.preventDefault();
106	    const res = await fetch('/api/lineitems', {
107	      method: 'POST',
108	      headers: { 'Content-Type': 'application/json' },
109	      body: JSON.stringify({
110	        invoiceId,
111	        description,
112	        qty: Number(qty),
113	        unit,
114	        unitPrice: Number(unitPrice),
115	      }),
116	    });
117	    if (res.ok) {
118	      const created: LineItem = await res.json();
119	      setLineItems((prev) => [...prev, created]);
120	      setDescription('');
121	      setQty('');
122	      setUnit('');
123	      setUnitPrice('');
124	    }
125	  }
126	
127	  async function onRemove(id: number) {
128	    const res = await fetch('/api/lineitems/remove', {
129	      method: 'POST',
130	      headers: { 'Content-Type': 'application/json' },
131	      body: JSON.stringify({ id }),
132	    });
133	    if (res.ok) {
134	      setLineItems((prev) => prev.filter((li) => li.id !== id));
135	      if (editingId === id) {
136	        setEditingId(null);
137	      }
138	    }
139	  }
140	
141	  function startEdit(li: LineItem) {
142	    setEditingId(li.id);
143	    setDraft({
144	      description: li.description,
145	      qty: String(li.qty),
146	      unit: li.unit,
147	      unitPrice: String(li.unitPrice),
148	    });
149	  }
150	
151	  async function onSaveEdit(id: number) {
152	    const res = await fetch('/api/lineitems/update', {
153	      method: 'POST',
154	      headers: { 'Content-Type': 'application/json' },
155	      body: JSON.stringify({
156	        id,
157	        description: draft.description,
158	        qty: Number(draft.qty),
159	        unit: draft.unit,
160	        unitPrice: Number(draft.unitPrice),
161	      }),
162	    });
163	    if (res.ok) {
164	      const updated: LineItem = await res.json();
165	      setLineItems((prev) => prev.map((li) => (li.id === id ? updated : li)));
166	      setEditingId(null);
167	    }
168	  }
169	
170	  // The subtotal is the sum of the line items; the discount is that percentage taken off it. Sales
171	  // tax is then added on top, worked out on the discounted amount (subtotal minus discount). The
172	  // final total is the discounted amount plus the tax.
173	  const subtotal = lineItems.reduce((sum, li) => sum + li.qty * Number(li.unitPrice), 0);
174	  const discount = subtotal * (discountPct / 100);
175	  const tax = (subtotal - discount) * (taxPct / 100);
176	  const total = subtotal - discount + tax;
177	
178	  return (
179	    <section data-testid="invoice-detail">
180	      <p>
181	        Status: <span data-testid="invoice-status">{status}</span>
182	      </p>
183	      <h3>Line items</h3>
184	      <form data-testid="lineitem-form" onSubmit={onSubmit}>
185	        <input
186	          data-testid="lineitem-form-description"
187	          placeholder="Description"
188	          value={description}
189	          onChange={(e) => setDescription(e.target.value)}
190	        />
191	        <input
192	          data-testid="lineitem-form-qty"
193	          placeholder="Qty"
194	          value={qty}
195	          onChange={(e) => setQty(e.target.value)}
196	        />
197	        <input
198	          data-testid="lineitem-form-unit"
199	          placeholder="Unit"
200	          value={unit}
201	          onChange={(e) => setUnit(e.target.value)}
202	        />
203	        <input
204	          data-testid="lineitem-form-unitprice"
205	          placeholder="Unit price"
206	          value={unitPrice}
207	          onChange={(e) => setUnitPrice(e.target.value)}
208	        />
209	        <button type="submit" data-testid="lineitem-form-submit">
210	          Add line item
211	        </button>
212	      </form>
213	
214	      <table data-testid="invoice-lineitems-table">
215	        <thead>
216	          <tr>
217	            <th>Description</th>
218	            <th>Qty</th>
219	            <th>Unit</th>
220	            <th>Unit price</th>
221	            <th>Amount</th>
222	            <th>Actions</th>
223	          </tr>
224	        </thead>
225	        <tbody>
226	          {lineItems.map((li) =>
227	            editingId === li.id ? (
228	              <tr key={li.id} data-testid={`lineitem-row-${li.id}`}>
229	                <td>
230	                  <input
231	                    data-testid={`lineitem-edit-description-${li.id}`}
232	                    value={draft.description}
233	                    onChange={(e) => setDraft((d) => ({ ...d, description: e.target.value }))}
234	                  />
235	                </td>
236	                <td>
237	                  <input
238	                    data-testid={`lineitem-edit-qty-${li.id}`}
239	                    value={draft.qty}
240	                    onChange={(e) => setDraft((d) => ({ ...d, qty: e.target.value }))}
241	                  />
242	                </td>
243	                <td>
244	                  <input
245	                    data-testid={`lineitem-edit-unit-${li.id}`}
246	                    value={draft.unit}
247	                    onChange={(e) => setDraft((d) => ({ ...d, unit: e.target.value }))}
248	                  />
249	                </td>
250	                <td>
251	                  <input
252	                    data-testid={`lineitem-edit-unitprice-${li.id}`}
253	                    value={draft.unitPrice}
254	                    onChange={(e) => setDraft((d) => ({ ...d, unitPrice: e.target.value }))}
255	                  />
256	                </td>
257	                <td data-testid="lineitem-amount">
258	                  {money(Number(draft.qty) * Number(draft.unitPrice))}
259	                </td>
260	                <td>
261	                  <button
262	                    type="button"
263	                    data-testid={`lineitem-save-${li.id}`}
264	                    onClick={() => void onSaveEdit(li.id)}
265	                  >
266	                    Save
267	                  </button>
268	                  <button
269	                    type="button"
270	                    data-testid={`lineitem-cancel-${li.id}`}
271	                    onClick={() => setEditingId(null)}
272	                  >
273	                    Cancel
274	                  </button>
275	                </td>
276	              </tr>
277	            ) : (
278	              <tr key={li.id} data-testid={`lineitem-row-${li.id}`}>
279	                <td data-testid="lineitem-description">{li.description}</td>
280	                <td data-testid="lineitem-qty">{li.qty}</td>
281	                <td data-testid="lineitem-unit">{li.unit}</td>
282	                <td data-testid="lineitem-unitprice">{money(li.unitPrice)}</td>
283	                <td data-testid="lineitem-amount">{money(li.qty * Number(li.unitPrice))}</td>
284	                <td>
285	                  <button
286	                    type="button"
287	                    data-testid={`lineitem-edit-${li.id}`}
288	                    onClick={() => startEdit(li)}
289	                  >
290	                    Edit
291	                  </button>
292	                  <button
293	                    type="button"
294	                    data-testid={`lineitem-remove-${li.id}`}
295	                    onClick={() => void onRemove(li.id)}
296	                  >
297	                    Remove
298	                  </button>
299	                </td>
300	              </tr>
301	            ),
302	          )}
303	        </tbody>
304	      </table>
305	
306	      <p>
307	        Subtotal: <span data-testid="invoice-subtotal">{money(subtotal)}</span>
308	      </p>
309	      <p>
