1	import React, { useEffect, useState } from 'react';
2	import { InvoiceDetail } from './InvoiceDetail';
3	
4	// A project's invoices, shown when a project is opened from the projects list. Owns its own state
5	// (CLAUDE.md — features own their state). Lists the project's invoices, a derived total, and a form
6	// to add one. Amounts render with 2 decimals.
7	type Invoice = {
8	  id: number;
9	  projectId: number;
10	  amount: number;
11	  status: string;
12	  issuedDate: string | null;
13	  dueDate: string | null;
14	  due: number;
15	};
16	
17	function money(n: number): string {
18	  return Number(n).toLocaleString('en-US', { style: 'currency', currency: 'USD' });
19	}
20	
21	export function ProjectInvoices({ projectId }: { projectId: number }) {
22	  const [invoices, setInvoices] = useState<Invoice[]>([]);
23	  const [amount, setAmount] = useState('');
24	  const [amountError, setAmountError] = useState('');
25	  const [sort, setSort] = useState('');
26	  const [openInvoiceId, setOpenInvoiceId] = useState<number | null>(null);
27	
28	  async function load(sortBy = sort) {
29	    const query = sortBy ? `&sort=${encodeURIComponent(sortBy)}` : '';
30	    const res = await fetch(`/api/invoices?projectId=${projectId}${query}`);
31	    if (res.ok) {
32	      setInvoices(await res.json());
33	    }
34	  }
35	
36	  useEffect(() => {
37	    void load();
38	  }, [projectId]);
39	
40	  function sortByDue() {
41	    setSort('due');
42	    void load('due');
43	  }
44	
45	  async function onSubmit(e: React.FormEvent) {
46	    e.preventDefault();
47	    const parsed = Number(amount);
48	    if (!Number.isFinite(parsed) || parsed <= 0) {
49	      setAmountError('Amount must be more than zero.');
50	      return;
51	    }
52	    setAmountError('');
53	    const res = await fetch('/api/invoices', {
54	      method: 'POST',
55	      headers: { 'Content-Type': 'application/json' },
56	      body: JSON.stringify({ projectId, amount: Number(amount) }),
57	    });
58	    if (res.ok) {
59	      const created: Invoice = await res.json();
60	      setInvoices((prev) => [...prev, created]);
61	      setAmount('');
62	    }
63	  }
64	
65	  async function sendInvoice(id: number) {
66	    const res = await fetch('/api/invoices/send', {
67	      method: 'POST',
68	      headers: { 'Content-Type': 'application/json' },
69	      body: JSON.stringify({ id }),
70	    });
71	    if (res.ok) {
72	      const sent: Invoice = await res.json();
73	      setInvoices((prev) => prev.map((inv) => (inv.id === sent.id ? sent : inv)));
74	    }
75	  }
76	
77	  // Cancel (void) an invoice sent by mistake: it reads VOID and stops counting toward money owed.
78	  async function cancelInvoice(id: number) {
79	    const res = await fetch('/api/invoices/cancel', {
80	      method: 'POST',
81	      headers: { 'Content-Type': 'application/json' },
82	      body: JSON.stringify({ id }),
83	    });
84	    if (res.ok) {
85	      const voided: Invoice = await res.json();
86	      setInvoices((prev) => prev.map((inv) => (inv.id === voided.id ? voided : inv)));
87	    }
88	  }
89	
90	  const total = invoices.reduce((sum, inv) => sum + Number(inv.amount), 0);
91	
92	  return (
93	    <section data-testid="project-invoices">
94	      <h2>Invoices</h2>
95	      <form data-testid="invoice-form" onSubmit={onSubmit}>
96	        <input
97	          data-testid="invoice-form-amount"
98	          placeholder="Amount"
99	          value={amount}
100	          onChange={(e) => setAmount(e.target.value)}
101	        />
102	        <button type="submit" data-testid="invoice-form-submit">
103	          Add invoice
104	        </button>
105	        {amountError ? (
106	          <p data-testid="invoice-form-amount-error" role="alert">
107	            {amountError}
108	          </p>
109	        ) : null}
110	      </form>
111	
112	      {openInvoiceId !== null ? (
113	        <InvoiceDetail invoiceId={openInvoiceId} />
114	      ) : (
115	        <>
116	      <div data-testid="invoice-controls">
117	        <button type="button" data-testid="invoice-sort-due" onClick={sortByDue}>
118	          Sort by due date
119	        </button>
120	      </div>
121	
122	      <table data-testid="project-invoices-table">
123	        <thead>
124	          <tr>
125	            <th>Amount</th>
126	            <th>Still due</th>
127	            <th>Issued</th>
128	            <th>Due</th>
129	            <th>Status</th>
130	            <th />
131	          </tr>
132	        </thead>
133	        <tbody>
134	          {invoices.map((inv) => (
135	            <tr key={inv.id} data-testid={`invoice-row-${inv.id}`}>
136	              <td data-testid="invoice-amount">{money(inv.amount)}</td>
137	              <td data-testid="invoice-due-amount">{money(inv.due)}</td>
138	              <td data-testid="invoice-issued">{inv.issuedDate ?? ''}</td>
139	              <td data-testid="invoice-due">{inv.dueDate ?? ''}</td>
140	              <td data-testid="invoice-status">{inv.status}</td>
141	              <td>
142	                <button
143	                  type="button"
144	                  data-testid={`invoice-open-${inv.id}`}
145	                  onClick={() => setOpenInvoiceId(inv.id)}
146	                >
147	                  Open
148	                </button>
149	                {inv.status === 'DRAFT' ? (
150	                  <button
151	                    type="button"
152	                    data-testid={`invoice-send-${inv.id}`}
153	                    onClick={() => void sendInvoice(inv.id)}
154	                  >
155	                    Send
156	                  </button>
157	                ) : null}
158	                {inv.status === 'SENT' ? (
159	                  <button
160	                    type="button"
161	                    data-testid={`invoice-cancel-${inv.id}`}
162	                    onClick={() => void cancelInvoice(inv.id)}
163	                  >
164	                    Cancel
165	                  </button>
166	                ) : null}
167	              </td>
168	            </tr>
169	          ))}
170	        </tbody>
171	        <tfoot>
172	          <tr>
173	            <td data-testid="project-invoices-total">{money(total)}</td>
174	          </tr>
175	        </tfoot>
176	      </table>
177	        </>
178	      )}
179	    </section>
180	  );
181	}
